import { useState } from 'react';
import {
  JxCard,
  JxStepper,
  JxStep,
  JxInput,
  JxButton,
  JxStack,
  JxText,
  JxDivider,
} from '@jinx-ui/react';

type ContactData = {
  fullName: string;
  email: string;
  phone: string;
};

type AddressData = {
  country: string;
  city: string;
  street: string;
  zip: string;
};

export type RegistrationFormData = {
  contact: ContactData;
  address: AddressData;
};

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationFormData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [contact, setContact] = useState<ContactData>({
    fullName: '',
    email: '',
    phone: '',
  });
  const [address, setAddress] = useState<AddressData>({
    country: '',
    city: '',
    street: '',
    zip: '',
  });

  const isLastStep = currentStep === STEPS.length - 1;

  const handleNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const handleBack = () => {
    setCurrentStep((step) => Math.max(0, step - 1));
  };

  const handleSubmit = () => {
    onSubmit({ contact, address });
  };

  const updateContact = (field: keyof ContactData) => (value: string) => {
    setContact((prev) => ({ ...prev, [field]: value }));
  };

  const updateAddress = (field: keyof AddressData) => (value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 'var(--jx-size-md)' }}>
      <JxStepper activeStep={currentStep} className="jx-mb-lg">
        {STEPS.map((label) => (
          <JxStep key={label} label={label} />
        ))}
      </JxStepper>

      <JxDivider className="jx-mb-lg" />

      {currentStep === 0 && (
        <JxStack direction="column" gap="md">
          <JxText variant="heading-sm">Контакты</JxText>
          <JxInput
            label="Полное имя"
            placeholder="Иван Иванов"
            value={contact.fullName}
            onChange={updateContact('fullName')}
          />
          <JxInput
            label="Email"
            type="email"
            placeholder="ivan@example.com"
            value={contact.email}
            onChange={updateContact('email')}
          />
          <JxInput
            label="Телефон"
            type="tel"
            placeholder="+7 900 000-00-00"
            value={contact.phone}
            onChange={updateContact('phone')}
          />
        </JxStack>
      )}

      {currentStep === 1 && (
        <JxStack direction="column" gap="md">
          <JxText variant="heading-sm">Адрес</JxText>
          <JxInput
            label="Страна"
            placeholder="Россия"
            value={address.country}
            onChange={updateAddress('country')}
          />
          <JxInput
            label="Город"
            placeholder="Москва"
            value={address.city}
            onChange={updateAddress('city')}
          />
          <JxInput
            label="Улица и дом"
            placeholder="ул. Ленина, д. 1"
            value={address.street}
            onChange={updateAddress('street')}
          />
          <JxInput
            label="Индекс"
            placeholder="123456"
            value={address.zip}
            onChange={updateAddress('zip')}
          />
        </JxStack>
      )}

      {currentStep === 2 && (
        <JxStack direction="column" gap="md">
          <JxText variant="heading-sm">Проверка</JxText>

          <JxText variant="label" style={{ color: 'var(--jx-color-text-secondary)' }}>
            Контакты
          </JxText>
          <JxText>{contact.fullName || '—'}</JxText>
          <JxText>{contact.email || '—'}</JxText>
          <JxText>{contact.phone || '—'}</JxText>

          <JxDivider />

          <JxText variant="label" style={{ color: 'var(--jx-color-text-secondary)' }}>
            Адрес
          </JxText>
          <JxText>
            {address.country || '—'}, {address.city || '—'}
          </JxText>
          <JxText>{address.street || '—'}</JxText>
          <JxText>{address.zip || '—'}</JxText>
        </JxStack>
      )}

      <JxDivider className="jx-mt-lg jx-mb-lg" />

      <JxStack direction="row" justify="space-between">
        <JxButton
          variant="secondary"
          onClick={handleBack}
          disabled={currentStep === 0}
        >
          Назад
        </JxButton>

        {isLastStep ? (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleNext}>
            Дальше
          </JxButton>
        )}
      </JxStack>
    </JxCard>
  );
}

